// Trusted synthetic Page->Tenant->Store map. NOT a real HMAC verifier.
// Raw byte HMAC is exercised in GitHub PR119 Node integration CI.
const pageRegistry={
 PAGE_QA_A:{tenant:'TENANT_QA_1',store:'SHOP_QA_A',priceVnd:159000,stock:25,sku:'A002'},
 PAGE_QA_B:{tenant:'TENANT_QA_1',store:'SHOP_QA_B',priceVnd:209000,stock:8,sku:'A002'}
};
const quotePattern=/(?:báo giá|giá|bao nhiêu|còn hàng|tồn kho)/iu;
const confirmCode=/^XAC NHAN (QA-[A-F0-9]{12})$/u;
const orderIntent=/^Tôi muốn đặt ([1-9][0-9]{0,3}) áo ([A-Z][A-Z0-9]+)$/iu;
return $input.all().map(v=>{
 const x=v.json||{};
 const emit=(status,reason)=>({json:{...x,planningState:status,
    plannedTool:null,plannedArgs:{},trustedStore:null,reason}});
 if(x.syntheticSignedFixture!==true||x.syntheticOnly!==true)
  return emit('REJECTED','NO_REAL_SIGNATURE_EVIDENCE');
 if(x.syntheticAgentProposal?.args &&
    Object.keys(x.syntheticAgentProposal.args).some(k=>/^(tenantId|storeId|pageId|role|isAdmin|verified|dryRun|force)$/i.test(k)))
  return emit('REJECTED','SCOPE_OR_AUTH_FIELD_DENIED');
 const page=pageRegistry[x.pageKey];
 if(!page)return emit('REJECTED','UNKNOWN_QA_PAGE');
 let tool=null,args={},text=String(x.signedFixtureText||'');
 if(x.syntheticAgentProposal){
  tool=x.syntheticAgentProposal.tool;args=x.syntheticAgentProposal.args||{};
 }else if(confirmCode.test(text)){
  tool='qa.order.confirm';args={confirmationCode:confirmCode.exec(text)[1]};
 }else if(orderIntent.test(text)){
  const m=orderIntent.exec(text);tool='qa.order.prepare';
  args={sku:m[2].toUpperCase(),quantity:Number(m[1]),
    expectedTotalVnd:Number(m[1])*page.priceVnd};
 }else if(quotePattern.test(text)){
  tool='quote.read';args={sku:'A002',quantity:1};
 }else if(/(?:sản phẩm|tư vấn)/iu.test(text)){
  tool='catalog.read';args={sku:'A002'};
 }else if(/(?:xin chào|chào)/iu.test(text)){
  tool='qa.greeting';args={};
 }
 return {json:{...x,planningState:'PROPOSED',plannedTool:tool,
  plannedArgs:args,trustedStore:page,reason:null}};
});

