// The only mock tool boundary. NO actual n8n tool connector is present.
const allow=new Set(['catalog.read','quote.read','qa.order.prepare','qa.order.confirm','qa.greeting']);
const pending=new Map(),mockOrders=new Map();
const CONFIRM_CODE='QA-A1B2C3D4E5F6';
return $input.all().map(v=>{
 const x=v.json||{},s=x.trustedStore||null,args=x.plannedArgs||{},tool=x.plannedTool||null;
 const base={scenario:x.scenario,expectedState:x.expectedState,
   toolProposal:tool,syntheticOnly:true,actualMetaSignatureVerified:false,
   actualRealLlmCalled:false,realToolExecutions:0,realOrders:0,
   providerSends:0,googleSheetsWrites:0,hostedWrites:0,stockWrites:0};
 const deny=reason=>({json:{...base,state:'DENIED',reason,reply:'[QA] Từ chối; không có đơn thật.'}});
 const ok=(state,reply)=>({json:{...base,state,reason:null,reply}});
 if(x.syntheticSignedFixture!==true||x.planningState!=='PROPOSED'||!s)
  return deny(x.reason||'QA_CONTEXT_NOT_VERIFIED');
 if(!allow.has(tool))return deny('TOOL_DENIED_BEFORE_EXECUTION');
 if(tool==='qa.greeting')return ok('QA_REPLY_READY','[QA] Xin chào! Đây là bot mô phỏng, không gửi Messenger.');
 if(!Object.keys(args).every(k=>!(/^(tenantId|storeId|pageId|role|isAdmin|dryRun|force)$/i.test(k))))
  return deny('UNTRUSTED_SCOPE_OVERRIDE');
 if(args.sku!==undefined&&args.sku!==s.sku)return deny('SKU_NOT_IN_THIS_SHOP');
 if(tool==='catalog.read')return ok('QA_REPLY_READY','[QA] A002 tồn mẫu '+s.stock+'. Không ghi đơn.');
 if(tool==='quote.read'){
  if(!Number.isSafeInteger(args.quantity)||args.quantity<1)return deny('QTY_INVALID');
  return ok('QA_REPLY_READY','[QA] A002 giá mô phỏng '+s.priceVnd+' VND, tồn '+s.stock+'.');
 }
 if(tool==='qa.order.prepare'){
  if(!/^Tôi muốn đặt [1-9][0-9]{0,3} áo [A-Z][A-Z0-9]+$/iu.test(x.signedFixtureText))
   return deny('SIGNED_ORDER_INTENT_REQUIRED');
  if(!Number.isSafeInteger(args.quantity)||args.quantity<1)return deny('INVALID_QUANTITY');
  if(args.quantity>s.stock)return deny('INSUFFICIENT_STOCK');
  if(args.expectedTotalVnd!==args.quantity*s.priceVnd)return deny('EXPECTED_TOTAL_MISMATCH');
  const key=x.pageKey+'|'+x.syntheticBuyer;
  pending.set(key,{code:CONFIRM_CODE,total:args.expectedTotalVnd});
  return ok('QA_CONFIRMATION_REQUIRED','[QA] Đang chờ xác nhận '+CONFIRM_CODE+'. Chưa tạo đơn.');
 }
 if(tool==='qa.order.confirm'){
  const key=x.pageKey+'|'+x.syntheticBuyer,p=pending.get(key);
  if(!p)return deny('NO_PENDING_OR_OTHER_SENDER');
  if(args.confirmationCode!==p.code||x.signedFixtureText!=='XAC NHAN '+p.code)
   return deny('SIGNED_CONFIRMATION_REQUIRED');
  if(!mockOrders.has(key))mockOrders.set(key,{qaCode:CONFIRM_CODE,real:false});
  return ok('QA_MOCK_CONFIRMED_NOT_SAVED','[QA] Đã xác nhận mô phỏng; không có đơn thật. Mã '+CONFIRM_CODE);
 }
 return deny('DEFAULT_DENY');
});

